kIn = input(7, "K Neighbors", 1, 15, 1)
featLen = input(20, "Feature Window", 5, 40, 1)
marginThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
agreeThresh = input(0.65, "Agreement Threshold", 0.5, 1.0, 0.01)
maxHist = input(300, "Max History for Search", 50, 500, 10)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

varip closeHist = array()
varip targetHist = array()

n0 = array.size(closeHist)
prevClose = close
if n0 > 0 {
    prevClose := closeHist[n0 - 1]
}

dirTarget = -1
if close > prevClose {
    dirTarget := 1
}

array.push(closeHist, close)
array.push(targetHist, dirTarget)

numBars = array.size(closeHist)
ready = numBars > featLen + 2 and bar_index > featLen + 2

bullVotes = 0
bearVotes = 0

if ready {
    bestDist = array()
    bestTargets = array()
    ii = 0
    while ii < kIn {
        array.push(bestDist, 999999.0)
        array.push(bestTargets, 0)
        ii := ii + 1
    }
    searchStart = numBars - 1 - maxHist
    if searchStart < featLen + 1 {
        searchStart := featLen + 1
    }
    if searchStart < 0 {
        searchStart := 0
    }
    j = searchStart
    while j < numBars - 1 {
        dist = 0.0
        n = 0
        while n < featLen {
            curIdx = numBars - 1 - featLen + 1 + n
            pastIdx = j - featLen + 1 + n
            curC = closeHist[curIdx]
            curP = closeHist[curIdx - 1]
            pastC = closeHist[pastIdx]
            pastP = closeHist[pastIdx - 1]
            curR = 0.0
            pastR = 0.0
            if curP != 0 {
                curR := (curC - curP) / curP
            }
            if pastP != 0 {
                pastR := (pastC - pastP) / pastP
            }
            d = curR - pastR
            dist := dist + d * d
            n := n + 1
        }
        insertIdx = -1
        m = 0
        while m < kIn {
            if dist < bestDist[m] {
                insertIdx := m
                m := kIn
            }
            m := m + 1
        }
        if insertIdx >= 0 {
            m = kIn - 1
            while m > insertIdx {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestTargets, m, bestTargets[m - 1])
                m := m - 1
            }
            array.set(bestDist, insertIdx, dist)
            array.set(bestTargets, insertIdx, targetHist[j])
        }
        j := j + 1
    }
    m = 0
    while m < kIn {
        if bestDist[m] < 999999.0 {
            if bestTargets[m] == 1 {
                bullVotes := bullVotes + 1
            } else {
                bearVotes := bearVotes + 1
            }
        }
        m := m + 1
    }
}

kFloat = kIn * 1.0
voteMargin = 0.0
if kFloat > 0 {
    voteMargin := (bullVotes - bearVotes) / kFloat
}
agreement = abs(voteMargin)
disagreement = 1.0 - agreement
marginNorm = (voteMargin + 1.0) / 2.0

buyCond = ready and voteMargin > marginThresh and agreement > agreeThresh
sellCond = ready and voteMargin < 0.0 - marginThresh and agreement > agreeThresh
buyCondPrev = buyCond[1]
sellCondPrev = sellCond[1]
buySig = buyCond and not buyCondPrev
sellSig = sellCond and not sellCondPrev

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

if ready {
    if voteMargin > 0 {
        bgcolor("rgba(34,204,136,0.05)")
    }
    if voteMargin < 0 {
        bgcolor("rgba(255,68,119,0.05)")
    }
}

plot(voteMargin, "Vote Margin", "#b48cff", 2, "separate")
plot(agreement, "Agreement", "#ffd43b", 2, "separate")
hline(0.43, "rgba(180,140,255,0.6)", "separate")
