hline(0.65, "rgba(255,212,59,0.6)", "separate")

plot3d(voteMargin * 10, "Vote Margin Pillars", "bars3d", "#b48cff", "separate")
plot3d(agreement * 10, "Agreement Sheet", "ribbon", "#ffd43b", "separate", 1)

if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize, 0, "separate")
}

sessMode = input("Visible Bars", "Session Mode")
sessLen = input(120, "Visible Session Bars", 20, 300, 5)
profRows = input(24, "Profile Rows", 8, 48, 1)
vaCover = input(70, "Value Area Coverage", 50, 90, 5)
showVA = input(true, "Show Value Area")
showPOC = input(true, "Show POC Rail")
enable3D = input(true, "Enable 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
rowH = rng / profRows
if rowH <= 0 {
    rowH := close * 0.001
}

// ─── Build row volumes: proportional overlap assignment ──────────
rowVols = array()
i = 0
while i < profRows {
    array.push(rowVols, 0.0)
    i := i + 1
}

b = 0
while b < sessLen {
    barH = high[b]
    barL = low[b]
    barV = volume[b]
    barR = barH - barL
    r = 0
    while r < profRows {
        rowLow = ll + r * rowH
        rowHigh = rowLow + rowH
        top = barH
        if rowHigh < top {
            top := rowHigh
        }
        bot = barL
        if rowLow > bot {
            bot := rowLow
        }
        ov = top - bot
        if ov > 0 and barV > 0 {
            share = 0.0
            if barR > 0 {
                share := ov / barR
            } else {
                share := 1.0
            }
            old = array.get(rowVols, r)
            array.set(rowVols, r, old + barV * share)
        }
        r := r + 1
    }
    b := b + 1
}

totalVol = array.sum(rowVols)

// ─── Point of control: highest-volume row ────────────────────────
pocRow = 0
pocVol = array.get(rowVols, 0)
i = 1
while i < profRows {
    v = array.get(rowVols, i)
    if v > pocVol {
        pocVol := v
        pocRow := i
    }
    i := i + 1
}
pocPrice = ll + (pocRow + 0.5) * rowH

// ─── Value area: expand from POC until coverage reached ──────────
vaLow = pocRow
vaHigh = pocRow
accum = pocVol
target = totalVol * vaCover / 100
guard = 0
while accum < target and guard < profRows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(rowVols, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < profRows - 1 {
        rightVal := array.get(rowVols, vaHigh + 1)
    }
    if rightVal >= leftVal and vaHigh < profRows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) * rowH
valPrice = ll + vaLow * rowH
vaW = vahPrice - valPrice
if vaW <= 0 {
    vaW := rowH
}

// ─── Value position + volume at current price row ────────────────
valPos = (close - valPrice) / vaW
closeRow = floor((close - ll) / rowH)
if closeRow < 0 {
    closeRow := 0
}
if closeRow > profRows - 1 {
    closeRow := profRows - 1
}
volAtPrice = array.get(rowVols, closeRow)
volNorm = 0.0
if totalVol > 0 {
    volNorm := volAtPrice / totalVol * 100
}
pocDom = 0.0
if totalVol > 0 {
    pocDom := pocVol / totalVol * 100
}
insideNow = close >= valPrice and close <= vahPrice
insidePrev = close[1] >= valPrice[1] and close[1] <= vahPrice[1]

// ─── Signals: price leaving value ────────────────────────────────
buySig = insidePrev and close > vahPrice and volume > 0
sellSig = insidePrev and close < valPrice and volume > 0

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 1, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize, 1, "3d")
}

// ─── POC rail label: only on newly established POC row ───────────
var lastPocRow = -1
if pocRow != lastPocRow {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 1, "3d")
}
lastPocRow := pocRow

// ─── 2D: same POC / VAH / VAL information when 3D is off ─────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(valPos * 100, "Value Position", "#4488ff", 1, "separate")
plot(volNorm, "Row Volume At Price", "#b48cff", 1, "separate")
hline(100, "#22cc88", "separate")
hline(0, "#ff4477", "separate")

// ─── 3D: value terrain + POC labelled rail + value rails ─────────
plot3d(volNorm, "Value Terrain", "surface", "#4488ff", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 2)

if insideNow {
    bgcolor("rgba(68,136,255,0.05)")
} else {
    bgcolor("rgba(255,136,0,0.06)")
}

// Fix 1: var lvl = highest(high, 20) froze at bar 0 — changed to plain assignment recomputed every bar.
// Fix 2: close[-1] is a future leak — changed to close for a current-bar breakout test.
