wxIn = input(1.0, "Wind Dir X", -5.0, 5.0, 0.1)
wyIn = input(0.0, "Wind Dir Y", -5.0, 5.0, 0.1)
wzIn = input(0.0, "Wind Dir Z", -5.0, 5.0, 0.1)
speedIn = input(10.0, "Wind Speed Knots", 0.0, 100.0, 0.5)
baseTail = input(1.0, "Base Tail Length", 0.2, 5.0, 0.1)
lenPerKnot = input(0.1, "Length Per Knot", 0.01, 0.5, 0.01)
maxSpeed = input(50.0, "Max Speed Knots Gradient", 10.0, 100.0, 1.0)
alertLevel = input(30.0, "High Wind Alert Knots", 5.0, 80.0, 1.0)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

pi = 3.14159265
halfPi = 1.57079633
rad2deg = 57.29578

drift = (close - open) * 0.02
wx = wxIn + drift
wy = wyIn + drift * 0.5
wz = wzIn + (high - low) * 0.02
windSpeed = speedIn + abs(close - open) * 0.5

mag = sqrt(wx * wx + wy * wy + wz * wz)

var pnx = 1.0
var pny = 0.0
var pnz = 0.0

nxRaw = wx / (mag + 0.000001)
nyRaw = wy / (mag + 0.000001)
nzRaw = wz / (mag + 0.000001)

nx = 0.0
ny = 0.0
nz = 0.0
if mag > 0.000001 {
  nx = nxRaw
  ny = nyRaw
  nz = nzRaw
} else {
  nx = pnx
  ny = pny
  nz = pnz
}
pnx := nx
pny := ny
pnz := nz

nxAdj = nx + 0.000001
ratioYaw = ny / nxAdj
absRatioYaw = abs(ratioYaw)
atanAbsYaw = 0.0
if absRatioYaw <= 1.0 {
  atanAbsYaw = absRatioYaw / (1.0 + 0.28 * absRatioYaw * absRatioYaw)
} else {
  invYaw = 1.0 / (absRatioYaw + 0.000001)
  atanInvYaw = invYaw / (1.0 + 0.28 * invYaw * invYaw)
  atanAbsYaw = halfPi - atanInvYaw
}
atanYaw = atanAbsYaw
if ratioYaw < 0.0 {
  atanYaw = 0.0 - atanAbsYaw
}
yawRad = atanYaw
if nxAdj < 0.0 {
  if ny >= 0.0 {
    yawRad = atanYaw + pi
  } else {
    yawRad = atanYaw - pi
  }
}
yawDeg = yawRad * rad2deg

horiz = sqrt(nx * nx + ny * ny)
horizSafe = horiz + 0.000001
ratioPitch = nz / horizSafe
absRatioPitch = abs(ratioPitch)
atanAbsPitch = 0.0
if absRatioPitch <= 1.0 {
  atanAbsPitch = absRatioPitch / (1.0 + 0.28 * absRatioPitch * absRatioPitch)
} else {
  invPitch = 1.0 / (absRatioPitch + 0.000001)
  atanInvPitch = invPitch / (1.0 + 0.28 * invPitch * invPitch)
  atanAbsPitch = halfPi - atanInvPitch
}
atanPitch = atanAbsPitch
if ratioPitch < 0.0 {
  atanPitch = 0.0 - atanAbsPitch
}
pitchRad = atanPitch
pitchDeg = pitchRad * rad2deg
rollDeg = 0.0

tailLen = baseTail + windSpeed * lenPerKnot
tRaw = windSpeed / maxSpeed
tClamped = tRaw
if tRaw > 1.0 {
  tClamped = 1.0
}
if tRaw < 0.0 {
  tClamped = 0.0
}
tGrad = tClamped
rComp = tGrad * 255.0
gComp = tGrad * 165.0
bComp = 255.0 - tGrad * 255.0

yawChg = abs(yawDeg - yawDeg[1])
pitchChg = abs(pitchDeg - pitchDeg[1])

highWindSig = crossover(windSpeed, alertLevel)
calmSig = crossunder(windSpeed, 5.0)
shiftRaw = (yawChg > 15.0 or pitchChg > 15.0) and windSpeed > alertLevel
shiftSig = shiftRaw and not shiftRaw[1]

if highWindSig {
  plotshape(bar_index, low, "HighWind", "triangleup", "#ff8800")
}
if calmSig {
  plotshape(bar_index, high, "Calm", "triangledown", "#3388ff")
}
if shiftSig {
  plotshape(bar_index, high, "Shift", "diamond", "#ff4477")
}

if highWindSig {
  plotshape_3d(bar_index, high, "HighWind", "coneup", "#ff8800", markerSize, 0, "separate", pitchDeg, yawDeg, rollDeg)
}
if calmSig {
  plotshape_3d(bar_index, low, "Calm", "conedown", "#3388ff", markerSize, 1, "separate", pitchDeg, yawDeg, rollDeg)
}
if shiftSig {
  plotshape_3d(bar_index, high, "Shift", "diamond", "#ff4477", markerSize, 2, "separate", pitchDeg, yawDeg, rollDeg)
}

plot(windSpeed, "Wind Speed kn", "#ff8800", 2, "separate")
plot(tailLen, "Tail Length", "#3388ff", 2, "separate")
plot(tGrad * 50.0, "Gradient t x50", "#22cc88", 1, "separate")
plot(yawDeg, "Yaw deg", "#b088ff", 1, "separate")

plot3d(tailLen, "Arrow Tail Length", "ribbon", "#3388ff", "separate", 0)
plot3d(windSpeed, "Wind Speed", "line3d", "#ff8800", "separate", 1)
plot3d(tGrad * 50.0, "Speed Gradient", "scatter", "#22cc88", "separate", 2)

crit = input(150, "Critical Threshold", 50, 300, 1)
disc_base_radius = input(1.0, "Disc Base Radius", 0.2, 3.0, 0.1)
spin_gain = input(0.5, "Spin Gain", 0.05, 2.0, 0.05)
max_rings = input(5, "Max Rings", 2, 8, 1)
ring_expansion_speed = input(2.0, "Ring Expansion Speed", 0.2, 5.0, 0.1)
ring_lifetime = input(3.0, "Ring Lifetime", 1.0, 10.0, 0.5)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

flow_psi = close
spinSpeed = flow_psi * spin_gain
locked = flow_psi > crit
overSig = locked and not locked[1]
clearSig = not locked and locked[1]

var disc_angle = 0.0
var lockAge = 0.0
var ringAge = 0.0

if locked {
  disc_angle := disc_angle[1]
} else {
  disc_angle := disc_angle[1] + spinSpeed
}

if locked {
  lockAge := lockAge[1] + 1
} else {
  lockAge := 0
}

if locked {
  if ringAge[1] > ring_lifetime {
    ringAge := 0
  } else {
    ringAge := ringAge[1] + 1
  }
} else {
  ringAge := 0
}

ringFront = close + disc_base_radius + ringAge * ring_expansion_speed * 0.5
spinTrace = spinSpeed + disc_base_radius

if overSig {
  plotshape(bar_index, low, "OVERPRESSURE", "triangleup", "#ff4477")
}

if clearSig {
  plotshape(bar_index, high, "Clear", "triangledown", "#22cc88")
}

